package fraymus.workspace;

import org.json.*;
import java.util.*;

final class PerceptionReport {
    static JSONArray checks(JSONObject g){return new JSONArray()
        .put(new JSONObject().put("selector","#verdict").put("expectText","Browser perception workflow verified"))
        .put(new JSONObject().put("selector","#goal-id").put("expectText",g.getString("id")))
        .put(new JSONObject().put("selector","#source-hash").put("expectText",g.getJSONObject("perceptionBinding").getString("sha256")))
        .put(new JSONObject().put("selector","#frames").put("expectText",Integer.toString(g.getJSONObject("metrics").getInt("frames"))))
        .put(new JSONObject().put("selector",".observed-frame").put("expectCount",2))
        .put(new JSONObject().put("selector","#mode").put("expectText",g.getString("mode")))
        .put(new JSONObject().put("selector","#trace").put("expectCount",1))
        .put(new JSONObject().put("selector","#scope").put("expectText","Source frames and tracking workflow verified. Categories and boxes retain their stated authority; personal identity and general visual learning are not established."));}
    static JSONObject build(JSONObject g,JSONObject run,PerceptionStore store) throws Exception {
        var metrics=PerceptionStore.metrics(run);var samples=run.getJSONArray("samples");var initial=store.frame(run.getString("initialFrameId"));var last=samples.getJSONObject(samples.length()-1);var finalFrame=store.frame(last.getString("frameId"));String firstImage=thumbnail(store.bytes(initial.getString("id"))),lastImage=thumbnail(store.bytes(finalFrame.getString("id")));var csv=new StringBuilder("sequence,captured_at_ms,track_id,label,status,page_x_css,page_y_css,appearance_match\n");var paths=new StringBuilder();var segments=new LinkedHashMap<String,StringBuilder>();double minX=Double.POSITIVE_INFINITY,minY=minX,maxX=Double.NEGATIVE_INFINITY,maxY=maxX;
        var points=new JSONArray();for(Object raw:samples){var s=(JSONObject)raw;var src=s.getJSONObject("source");var crop=src.getJSONObject("crop");for(Object value:s.getJSONArray("objects")){var o=(JSONObject)value;csv.append(s.getInt("sequence")).append(',').append(s.getDouble("capturedAt")).append(',').append(o.getString("id")).append(',').append(o.getString("label")).append(',').append(o.getString("status"));if(!o.isNull("box")){var b=o.getJSONArray("box");double x=src.getDouble("scrollX")+crop.getDouble("x")+(b.getDouble(0)+b.getDouble(2))/2*crop.getDouble("width"),y=src.getDouble("scrollY")+crop.getDouble("y")+(b.getDouble(1)+b.getDouble(3))/2*crop.getDouble("height");minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);points.put(new JSONObject().put("id",o.getString("id")).put("x",x).put("y",y));csv.append(',').append(x).append(',').append(y);}else{points.put(new JSONObject().put("id",o.getString("id")).put("lost",true));csv.append(",,");}csv.append(',').append(o.opt("matchScore")).append('\n');}}
        for(Object raw:points){var p=(JSONObject)raw;String id=p.getString("id");if(p.optBoolean("lost")){var prior=segments.remove(id);if(prior!=null)paths.append(polyline(prior));continue;}var segment=segments.computeIfAbsent(id,k->new StringBuilder());segment.append(String.format(Locale.ROOT,"%.3f,%.3f ",30+660*(p.getDouble("x")-minX)/Math.max(1,maxX-minX),30+240*(p.getDouble("y")-minY)/Math.max(1,maxY-minY)));}for(var segment:segments.values())paths.append(polyline(segment));
        String authority=run.getJSONObject("detection").getString("authority");String html="<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Browser perception evidence</title><style>body{margin:0;background:#edf3ef;color:#173b35;font:16px/1.55 system-ui}main{max-width:1000px;margin:auto;padding:26px}section{background:white;border:1px solid #bdcfc3;border-radius:12px;padding:20px;margin:20px 0}code,pre{white-space:pre-wrap;overflow-wrap:anywhere}.metrics{display:flex;gap:24px;flex-wrap:wrap}.metrics b{display:block;font-size:28px}.pictures{display:grid;grid-template-columns:1fr 1fr;gap:12px}.observed-frame,svg{width:100%;height:auto}h1{font-size:32px}@media(max-width:550px){.pictures{grid-template-columns:1fr}}</style><main><p>FRAYNIX / EDITION 022 / SOURCE-QUALIFIED PERCEPTION</p><h1 id='verdict'>Browser perception workflow verified</h1><section class='metrics'><div><b id='frames'>"+metrics.getInt("frames")+"</b>Actual sampled frames</div><div><b>"+String.format(Locale.ROOT,"%.1f%%",metrics.getDouble("trackedFraction")*100)+"</b>Tracked observations</div><div><b>"+metrics.getInt("lostObservations")+" / "+metrics.getInt("reacquisitions")+"</b>Lost / reacquired</div><div><b>"+metrics.getInt("appearanceUpdates")+"</b>Gated template updates</div></section><section><h2>Actual unannotated source frames</h2><div class='pictures'><figure><img class='observed-frame' alt='Initial browser pixel capture' src='data:image/jpeg;base64,"+firstImage+"'><figcaption>Initial source thumbnail, before overlays.</figcaption></figure><figure><img class='observed-frame' alt='Final browser pixel capture' src='data:image/jpeg;base64,"+lastImage+"'><figcaption>Final source thumbnail; original PNG retained with its hash.</figcaption></figure></div><h2>Page-space centre traces</h2><svg id='trace' viewBox='0 0 720 300' role='img' aria-label='Observed object centre paths, broken at lost intervals'>"+paths+"</svg><p>Each segment connects successive observed centres. Lost intervals break the line. These are sampled observations, not inferred invisible movement.</p></section><section><h2>Authority and source</h2><p>Mode: <b id='mode'>"+SpatialReport.escape(run.getString("mode"))+"</b></p><p>"+SpatialReport.escape(authority)+"</p><p id='scope'>Source frames and tracking workflow verified. Categories and boxes retain their stated authority; personal identity and general visual learning are not established.</p><p>URL: "+SpatialReport.escape(initial.getJSONObject("source").getString("url"))+"</p><p>Initial PNG SHA-256 <code id='source-hash'>"+initial.getString("sha256")+"</code></p><p>Goal <code id='goal-id'>"+g.getString("id")+"</code></p><details><summary>Actual metrics and detection</summary><pre>"+SpatialReport.escape(metrics.toString(2))+"\n"+SpatialReport.escape(run.getJSONObject("detection").toString(2))+"</pre></details></section></main></html>";
        var frames=new JSONArray().put(initial);for(Object raw:samples)frames.put(store.frame(((JSONObject)raw).getString("frameId")));
        var files=new JSONObject().put("index.html",html).put("perception-run.json",run.toString(2)).put("source-frames.json",frames.toString(2)).put("detection.json",run.getJSONObject("detection").toString(2)).put("motion.csv",csv.toString()).put("verification.json",metrics.toString(2));if(!run.getString("lessonId").isEmpty())files.put("taught-appearance.json",store.lesson(run.getString("lessonId")).toString(2));else if(run.getJSONObject("detection").optBoolean("memoryUsed")){var taught=new JSONArray();for(Object raw:run.getJSONObject("detection").getJSONArray("taughtExamples"))taught.put(store.lesson(((JSONObject)raw).getString("id")));files.put("taught-appearances.json",taught.toString(2));}
        return new JSONObject().put("title","Browser perception · "+g.getString("id").substring(0,8)).put("files",files).put("sources",new JSONArray().put("goal:"+g.getString("id")).put("perception-run:"+run.getString("id")).put("sha256:"+initial.getString("sha256")));
    }
    private static String thumbnail(byte[] bytes) throws Exception {var image=PerceptionStore.decode(bytes);double scale=Math.min(1,320.0/Math.max(image.getWidth(),image.getHeight()));var out=new java.awt.image.BufferedImage(Math.max(1,(int)(image.getWidth()*scale)),Math.max(1,(int)(image.getHeight()*scale)),java.awt.image.BufferedImage.TYPE_INT_RGB);var graphics=out.createGraphics();graphics.drawImage(image,0,0,out.getWidth(),out.getHeight(),null);graphics.dispose();var encoded=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(out,"jpg",encoded);return Base64.getEncoder().encodeToString(encoded.toByteArray());}
    private static String polyline(StringBuilder points){return "<polyline class='observed-path' fill='none' stroke='#147388' stroke-width='3' points='"+points+"'/>";}
}
